import javax.script.ScriptEngineManager;
import javax.script.ScriptException;
import java.util.Map;

public class DynamicMetricService {

    private final ScriptEngine engine;

    public DynamicMetricService() {
        ScriptEngineManager manager = new ScriptEngineManager();
        this.engine = manager.getEngineByName("JavaScript");
    }

    /**
     * Calculates a dynamic metric based on the provided formula and context.
     *
     * @param formula The mathematical or logical formula as a string (e.g., "(metricA + metricB) * 0.9")
     * @param context A map containing variable names and their corresponding values required by the formula
     * @return The computed result of the formula
     * @throws ScriptException If an error occurs during script evaluation
     */
    public Object calculate(String formula, Map<String, Object> context) throws ScriptException {
        if (formula == null || formula.trim().isEmpty()) {
            throw new ScriptException("Formula cannot be null or empty");
        }

        // Bind variables from the context to the script engine
        for (Map.Entry<String, Object> entry : context.entrySet()) {
            engine.put(entry.getKey(), entry.getValue());
        }

        // Evaluate the formula
        return engine.eval(formula);
    }
}
